6	import { MobileNav } from "./MobileNav";
7	import { Sidebar } from "./Sidebar";
8	
9	/* Collapse is persisted in a COOKIE, and its initial value is read on the
10	   server in app/(portal)/layout.tsx. localStorage is only readable after
11	   hydration, which would render a collapsed sidebar at full width and snap it
12	   narrow on every page load — the one animation nobody asked for. */
13	const COOKIE = "kodely-sidebar";
14	const YEAR = 60 * 60 * 24 * 365;
15	
16	/* The frame every portal page renders inside. Pages supply content only — no
17	   page owns its own navigation, header chrome or toast host, which is what
18	   let the old portal drift into several unrelated header treatments.
19	
20	   Collapse state lives HERE rather than inside Sidebar, because the main
21	   column's left offset has to move with the rail. When it lived in the
22	   sidebar the rail animated and the content stayed put, leaving a widening
23	   gap for the duration of the transition. */
24	export function AppShell({
25	  children,
26	  initialCollapsed,
27	  user,
28	  balance,
29	}: {
30	  children: ReactNode;
31	  initialCollapsed: boolean;
32	  user: { email: string; name: string | null };
33	  balance: number;
34	}) {
35	  const [collapsed, setCollapsed] = useState(initialCollapsed);
36	
37	  const toggle = () => {
38	    const next = !collapsed;
39	    setCollapsed(next);
40	    document.cookie = `${COOKIE}=${next ? "1" : "0"};path=/;max-age=${YEAR};samesite=lax`;
41	  };
42	
43	  return (
44	    <ToastProvider>
45	      <div className="k-shell min-h-dvh bg-canvas" data-collapsed={collapsed}>
46	        <Sidebar collapsed={collapsed} onToggle={toggle} user={user} balance={balance} />
47	        <MobileNav user={user} balance={balance} />
48	        {/* Both the rail's width and this offset read --shell-sidebar, so they
49	            animate off one value and cannot tear mid-transition. */}
50	        <div className="transition-[padding] duration-[var(--t-2)] ease-[var(--ease)] lg:pl-[var(--shell-sidebar)]">
51	          {/* pb-24 on small screens keeps the last row clear of the fixed
52	              bottom bar; without it the final card is permanently half-hidden
53	              and reads as a rendering bug. */}
54	          <main className="mx-auto w-full max-w-[1400px] px-4 pt-6 pb-24 sm:px-6 lg:px-8 lg:pt-8 lg:pb-14">
55	            {children}
56	          </main>
57	        </div>
58	      </div>
59	    </ToastProvider>
60	  );
61	}
