11	export const dynamic = "force-dynamic";
12	
13	/* The signed-in product shell: /dashboard/*, /settings, /support.
14	   Deliberately NOT wrapping /templates, /wizard, /pricing or /blog — those are
15	   public marketing pages with their own nav, and a signed-out visitor must
16	   still be able to read them. The portal has its own in-shell copies of the
17	   template gallery and the prompt entry for signed-in customers.
18	
19	   The builder (/projects/[id]) is also outside this group on purpose: it is
20	   full-bleed chat + preview and a 248px rail would take a fifth of the
21	   customer's site preview to show navigation they are not using while
22	   building. It carries its own back-to-dashboard affordance instead.
23	
24	   AUTH: this redirect is the primary gate, but every page below ALSO resolves
25	   the user itself. A layout does not re-render on every navigation within its
26	   own segment, and route handlers never sit under it at all — the same reason
27	   app/admin/layout.tsx says so in its own comment. */
28	export default async function PortalLayout({ children }: { children: ReactNode }) {
