    48	    setOpen(false);
    49	    setError(null);
    50	  }
    51	
    52	  function create() {
    53	    const trimmed = name.trim().slice(0, NAME_MAX).trim();
    54	    if (!trimmed) {
    55	      setError("Give the site a name — you can change it later.");
