     8	/* The one interactive element on the Domains page. Client only because the
     9	   clipboard is. The failure branch is not decoration: writeText rejects on an
    10	   insecure origin and in a few embedded browsers, and the customer has to end
    11	   up with the address either way — so the toast carries the text itself
    12	   rather than saying "copy failed" and leaving them with nothing. */
    13	export function CopyAddress({ url, siteName }: { url: string; siteName: string }) {
    14	  const push = useToast();
    15	  const [copied, setCopied] = useState(false);
    16	
    17	  function copy() {
    18	    navigator.clipboard.writeText(url).then(
    19	      () => {
    20	        setCopied(true);
    21	        setTimeout(() => setCopied(false), 1600);
    22	        push({ tone: "ok", message: `Address for ${siteName} copied.` });
    23	      },
    24	      () => {
    25	        push({ tone: "danger", message: `Couldn't reach the clipboard. The address is ${url}` });
    26	      },
    27	    );
    28	  }
    29	
    30	  return (
    31	    <IconButton
    32	      label={copied ? `Copied the address for ${siteName}` : `Copy the address for ${siteName}`}
    33	      variant="ghost"
    34	      size="sm"
    35	      onClick={copy}
    36	    >
    37	      {copied ? (
    38	        <Check className="size-4 text-ok" aria-hidden />
    39	      ) : (
    40	        <Copy className="size-4" aria-hidden />
