    10	/* The display name, and the only editable field on the account.
    11	   PUTs /api/account/profile, then router.refresh() — the name is rendered by
    12	   the sidebar, the avatar and the dashboard greeting, all of which are Server
    13	   Components above this one, so a refresh is what makes the whole shell agree
    14	   with the field instead of this input being the only thing that changed. */
    15	export default function NameForm({ initialName }: { initialName: string | null }) {
    16	  const router = useRouter();
    17	  const toast = useToast();
    18	  const [saved, setSaved] = useState(initialName ?? "");
    19	  const [value, setValue] = useState(initialName ?? "");
    20	  const [error, setError] = useState<string | null>(null);
    21	  const [saving, setSaving] = useState(false);
    22	  const [refreshing, startTransition] = useTransition();
    23	
    24	  // Compared against the last SAVED value rather than the initial prop, so the
    25	  // button goes quiet again after a save instead of staying lit until a
    26	  // navigation. Trimmed on both sides because trailing space is not an edit —
    27	  // the server would normalise it away and report nothing changed.
    28	  const dirty = value.trim() !== saved.trim();
    29	  const busy = saving || refreshing;
    30	
    31	  async function save() {
    32	    setSaving(true);
    33	    setError(null);
    34	    try {
    35	      const res = await fetch("/api/account/profile", {
    36	        method: "PUT",
    37	        headers: { "Content-Type": "application/json" },
    38	        // Empty clears the name; the route treats "" and null identically.
    39	        body: JSON.stringify({ name: value.trim() === "" ? null : value }),
    40	      });
    41	      const data = (await res.json()) as { name?: string | null; error?: string };
    42	      if (!res.ok) {
    43	        setError(data.error ?? "Couldn't save that.");
    44	        return;
    45	      }
    46	      // Show what was STORED, not what was typed: the server collapses runs of
    47	      // whitespace and strips invisible characters, and the field should not
    48	      // keep claiming otherwise.
    49	      const stored = data.name ?? "";
    50	      setSaved(stored);
    51	      setValue(stored);
    52	      toast({
    53	        tone: "ok",
