     8	/* The user's own ceiling on 30-day spend. The route (app/api/account/
     9	   spend-cap) is unchanged; this is the same PUT it always sent, wearing the
    10	   product's own controls instead of a hand-rolled checkbox and a bare input. */
    11	
    12	type Props = { initialCap: number | null; spent: number };
    13	
    14	export default function SpendCapForm({ initialCap, spent }: Props) {
    15	  const toast = useToast();
    16	  const [enabled, setEnabled] = useState(initialCap !== null);
    17	  const [value, setValue] = useState(initialCap === null ? "" : String(initialCap));
    18	  const [saving, setSaving] = useState(false);
    19	  const [error, setError] = useState<string | null>(null);
    20	
    21	  async function save() {
    22	    setSaving(true);
    23	    setError(null);
    24	
    25	    const cap = enabled ? Number(value) : null;
    26	    if (enabled && (!Number.isInteger(cap) || (cap as number) < 1)) {
    27	      setError("Enter a whole number of credits.");
    28	      setSaving(false);
    29	      return;
    30	    }
    31	
    32	    try {
    33	      const res = await fetch("/api/account/spend-cap", {
    34	        method: "PUT",
    35	        headers: { "Content-Type": "application/json" },
    36	        body: JSON.stringify({ cap }),
    37	      });
    38	      const data = (await res.json()) as { cap?: number | null; error?: string };
    39	      if (!res.ok) {
    40	        setError(data.error ?? "Couldn't save that.");
    41	        return;
    42	      }
    43	      toast({
    44	        tone: "ok",
    45	        message:
    46	          data.cap == null
    47	            ? "Cap removed. Builds will run until your credits run out."
    48	            : `Cap set to ${data.cap.toLocaleString()} credits per 30 days.`,
    49	      });
    50	    } catch {
    51	      setError("Couldn't reach the server. Try again.");
    52	    } finally {
    53	      setSaving(false);
    54	    }
    55	  }
    56	
    57	  // A cap at or below what has already gone through the rolling window stops
    58	  // builds the moment it is saved. That is a legitimate thing to want, but it
    59	  // is almost never what someone typing a number expects, so it is said before
    60	  // they press Save rather than discovered by a build refusing to start.
    61	  const typed = Number(value);
    62	  const stopsImmediately =
    63	    enabled && Number.isInteger(typed) && typed >= 1 && typed <= spent;
    64	
    65	  return (
    66	    <div className="mt-5">
    67	      <label className="flex w-fit cursor-pointer items-center gap-2.5 text-sm text-ink">
    68	        <input
    69	          type="checkbox"
    70	          checked={enabled}
    71	          onChange={(e) => {
    72	            setEnabled(e.target.checked);
    73	            setError(null);
    74	          }}
    75	          className="k-focus size-4 rounded-xs border-line-strong accent-brand"
    76	        />
    77	        Limit my spending
    78	      </label>
    79	
    80	      {enabled && (
    81	        <div className="mt-4 max-w-xs">
    82	          <Input
    83	            label="Credits per 30 days"
    84	            type="number"
    85	            min={1}
    86	            step={1}
    87	            inputMode="numeric"
    88	            value={value}
    89	            onChange={(e) => {
    90	              setValue(e.target.value);
    91	              setError(null);
    92	            }}
    93	            error={error ?? undefined}
    94	            placeholder="1000"
    95	            className="k-num"
    96	          />
    97	        </div>
    98	      )}
    99	
   100	      {!enabled && error != null && <p className="mt-3 text-xs text-danger">{error}</p>}
   101	
   102	      {stopsImmediately && error == null && (
   103	        <p className="mt-3 max-w-md text-xs leading-relaxed text-warn">
   104	          You have already spent <span className="k-num">{spent.toLocaleString()}</span> credits in
   105	          the last 30 days, so this cap stops builds as soon as you save it — until enough of that
   106	          spend falls out of the rolling window.
   107	        </p>
   108	      )}
   109	
   110	      <div className="mt-4 flex flex-wrap items-center gap-3">
   111	        {/* The one primary action on this page. */}
   112	        <Button variant="primary" size="sm" onClick={save} loading={saving}>
   113	          Save
   114	        </Button>
   115	        <span className="text-xs text-ink-3">
   116	          {enabled
   117	            ? "Builds stop when the cap is reached. Nothing else changes."
   118	            : "No cap. Builds run until your credit balance runs out."}
   119	        </span>
   120	      </div>
   121	    </div>
