39	  sessions: DisplaySession[];
40	  /** Live sessions in total, which may exceed `sessions.length` when truncated. */
41	  total: number;
42	  /**
43	   * Everything except the caller's own, counted on the server. Deriving it
44	   * from `sessions` would be wrong the moment the list is truncated and the
45	   * current session is not among the newest rows shown.
46	   */
47	  others: number;
48	  limit: number;
49	}) {
50	  const router = useRouter();
51	  const toast = useToast();
52	  const [revoking, setRevoking] = useState<string | null>(null);
53	  const [confirming, setConfirming] = useState<Scope | null>(null);
54	  const [bulkBusy, setBulkBusy] = useState(false);
55	  const [refreshing, startTransition] = useTransition();
56	
57	  async function revoke(body: { id: string } | { scope: Scope }) {
58	    const res = await fetch("/api/account/sessions", {
59	      method: "DELETE",
60	      headers: { "Content-Type": "application/json" },
61	      body: JSON.stringify(body),
62	    });
