64	  }
65	
66	  async function revokeOne(id: string) {
67	    setRevoking(id);
68	    try {
69	      const { res, data } = await revoke({ id });
70	      if (!res.ok) {
71	        toast({ tone: "danger", message: data.error ?? "Couldn't end that session." });
72	        return;
73	      }
74	      toast({ tone: "ok", message: "That session was signed out." });
75	      startTransition(() => router.refresh());
76	    } catch {
77	      toast({ tone: "danger", message: "Couldn't reach the server. Try again." });
78	    } finally {
79	      setRevoking(null);
80	    }
81	  }
82	
83	  async function revokeScope(scope: Scope) {
84	    setBulkBusy(true);
85	    try {
86	      const { res, data } = await revoke({ scope });
87	      if (!res.ok) {
88	        toast({ tone: "danger", message: data.error ?? "Couldn't end those sessions." });
89	        return;
90	      }
91	      setConfirming(null);
92	      if (data.signedOut) {
