103	      toast({
104	        tone: "ok",
105	        message:
106	          count === 0
107	            ? "There were no other sessions to sign out."
108	            : `Signed out ${count} other session${count === 1 ? "" : "s"}.`,
109	      });
110	      startTransition(() => router.refresh());
111	    } catch {
112	      toast({ tone: "danger", message: "Couldn't reach the server. Try again." });
113	    } finally {
114	      setBulkBusy(false);
115	    }
116	  }
117	
118	  return (
119	    <>
120	      <ul className="mt-5 divide-y divide-hair rounded-lg border border-hair">
121	        {sessions.map((session) => (
122	          <li
123	            key={session.id}
124	            className="flex flex-wrap items-center justify-between gap-x-4 gap-y-2 px-4 py-3"
125	          >
126	            <div className="min-w-0">
127	              <div className="flex items-center gap-2">
128	                <span className="text-sm font-medium text-ink">
129	                  Signed in{" "}
130	                  <time className="k-num" dateTime={session.createdAtIso}>
131	                    {session.createdAtLabel}
132	                  </time>
133	                </span>
134	                {session.current && (
135	                  <Badge tone="ok" dot>
136	                    This device
137	                  </Badge>
138	                )}
139	              </div>
140	              <p className="mt-0.5 text-xs text-ink-3">
141	                Expires{" "}
142	                <time className="k-num" dateTime={session.expiresAtIso}>
143	                  {session.expiresAtLabel}
144	                </time>
145	              </p>
146	            </div>
147	
148	            {session.current ? (
149	              <span className="text-xs text-ink-3">Sign out to end this one</span>
150	            ) : (
151	              <Button
152	                variant="ghost"
153	                size="sm"
154	                onClick={() => void revokeOne(session.id)}
155	                loading={revoking === session.id}
156	                disabled={bulkBusy || refreshing}
157	              >
158	                Sign out
159	              </Button>
160	            )}
161	          </li>
162	        ))}
163	      </ul>
164	
165	      {total > sessions.length && (
166	        <p className="mt-3 text-xs text-ink-3">
167	          Showing the {limit} most recent of{" "}
168	          <span className="k-num">{total.toLocaleString()}</span> active sessions. Signing out every
169	          other session below ends all of them, not just the ones listed.
170	        </p>
171	      )}
172	
173	      {others > 0 && (
174	        <div className="mt-4 flex flex-wrap items-center gap-3">
175	          <Button
176	            variant="secondary"
177	            size="sm"
178	            onClick={() => setConfirming("others")}
179	            disabled={bulkBusy || refreshing}
180	          >
181	            Sign out {others === 1 ? "the other session" : `all ${others} other sessions`}
182	          </Button>
183	          <button
184	            type="button"
185	            className="k-focus rounded-xs text-xs text-danger underline underline-offset-2 hover:no-underline disabled:opacity-45"
186	            onClick={() => setConfirming("all")}
187	            disabled={bulkBusy || refreshing}
188	          >
189	            Sign out everywhere, including this device
190	          </button>
191	        </div>
192	      )}
193	
194	      <ConfirmModal
195	        open={confirming === "others"}
196	        onClose={() => setConfirming(null)}
197	        onConfirm={() => void revokeScope("others")}
198	        title="Sign out every other session?"
199	        confirmLabel="Sign out others"
200	        busy={bulkBusy}
201	        body={
202	          <>
203	            Every other browser and device signed in to this account is signed out immediately, and
204	            has to sign in again. You stay signed in here. Nothing else about your account changes —
205	            no project, file or credit is touched.
206	          </>
207	        }
208	      />
209	
210	      <ConfirmModal
211	        open={confirming === "all"}
212	        onClose={() => setConfirming(null)}
213	        onConfirm={() => void revokeScope("all")}
214	        title="Sign out everywhere?"
215	        confirmLabel="Sign out everywhere"
216	        busy={bulkBusy}
217	        body={
218	          <>
219	            This one includes the browser you are using right now — you will be sent to the sign-in
220	            page and will need your password or Google account to get back in. Use it if you think
221	            somebody else has access. Nothing is deleted.
222	          </>
223	        }
224	      />
225	    </>
226	  );
