5	/* Everything both /dashboard and /dashboard/websites need to describe a site,
6	   in ONE place, because the two pages render the same card and must never
7	   disagree about what a site's state is.
8	
9	   This module is deliberately server-only-ish (it imports lib/db) but carries
10	   no "use client" directive and exports plain functions, so a Server Component
11	   can call it. WebsiteCard is the client half and only ever receives the plain
12	   objects produced here — no Date, no Prisma model, nothing that would have to
13	   be re-derived in the browser. */
14	
15	/**
16	 * How long a `Build.status = "RUNNING"` row is still believed.
17	 *
18	 * There is no cleanup for an abandoned build: the generate route streams over
19	 * SSE, and a dropped connection, a crashed process or a redeploy leaves the row
20	 * RUNNING forever. Rendering that as "Building…" would mean a site that claims
21	 * to be working on something for the rest of its life.
22	 *
23	 * The cut-off is not a guess. app/api/generate/route.ts sets
24	 * `export const maxDuration = 300` — the platform itself kills the request at
25	 * five minutes, so no build can legitimately still be running after that. This
26	 * is double it, which leaves room for clock skew and a slow final write while
27	 * still collapsing an abandoned row to "not building" within ten minutes.
28	 */
29	export const BUILD_STALE_MS = 10 * 60 * 1000;
30	
31	/** Minutes, for the sentence the UI shows about the rule above. */
32	export const BUILD_STALE_MINUTES = BUILD_STALE_MS / 60_000;
33	
34	/** Matches the constant in app/api/projects/[id]/publish/route.ts. */
35	const SITES_BASE = process.env.KODELY_SITES_BASE ?? "kodely.site";
