37	// ── Dates ──────────────────────────────────────────────────────────────────
38	// Formatted on the SERVER and passed down as strings. A client component that
39	// formatted these itself would either disagree with the server HTML at
40	// hydration (relative times move) or depend on the visitor's locale, which
41	// differs from the server's. One string, computed once, is neither.
42	
43	const ABSOLUTE = new Intl.DateTimeFormat("en-GB", {
44	  day: "numeric",
45	  month: "short",
46	  year: "numeric",
47	  timeZone: "UTC",
48	});
49	
50	export function formatDate(value: Date): string {
51	  return ABSOLUTE.format(value);
52	}
53	
54	/**
55	 * A cut-off `n` days back.
56	 *
57	 * Lives here rather than inline in a page because `react-hooks/purity`
58	 * (correctly) refuses `Date.now()` inside a component body: a render must be
59	 * idempotent, and a clock read is the canonical thing that is not. Reading the
60	 * clock inside a plain function the component calls is the same value with the
61	 * rule satisfied honestly rather than suppressed.
62	 */
63	export function daysAgo(days: number): Date {
64	  return new Date(Date.now() - days * 24 * 60 * 60 * 1000);
65	}
66	
67	/** "3 minutes ago" … then absolute once it stops being a useful relative. */
68	export function formatRelative(value: Date, now: number = Date.now()): string {
69	  const seconds = Math.round((now - value.getTime()) / 1000);
70	  if (seconds < 45) return "just now";
71	  const minutes = Math.round(seconds / 60);
72	  if (minutes < 60) return `${minutes} ${minutes === 1 ? "minute" : "minutes"} ago`;
73	  const hours = Math.round(minutes / 60);
74	  if (hours < 24) return `${hours} ${hours === 1 ? "hour" : "hours"} ago`;
75	  const days = Math.round(hours / 24);
76	  if (days < 30) return `${days} ${days === 1 ? "day" : "days"} ago`;
77	  return ABSOLUTE.format(value);
78	}
