80	// ── Generated covers ───────────────────────────────────────────────────────
81	//
82	// NOTHING IN THIS PRODUCT CAPTURES A SCREENSHOT. There is no thumbnail column,
83	// no headless browser, no image storage. So a card cannot show what a site
84	// looks like, and must not pretend to.
85	//
86	// What it CAN show is the site's own identity. If the project has a brand kit
87	// (lib/brand-kit.ts, stored as a ProjectFile with kind "brand") those are the
88	// real colours the generated site is painted with, and the cover is genuinely
89	// derived from the thing it represents. Without one, the cover falls back to a
90	// palette chosen deterministically from the slug — stable forever, distinct
91	// between neighbours in a grid, and obviously a generated mark rather than a
92	// picture of a page.
93	
94	/** Fallback covers. Curated pairs, not random hues, so a grid stays coherent. */
95	const COVER_PALETTES: readonly (readonly [string, string])[] = [
96	  ["#f72570", "#a33dff"],
97	  ["#0ea5e9", "#2563eb"],
98	  ["#14b8a6", "#0e7490"],
99	  ["#f97316", "#dc2626"],
100	  ["#6366f1", "#a855f7"],
101	  ["#22d3ee", "#7c3aed"],
102	  ["#84cc16", "#0d8f5b"],
103	  ["#fb7185", "#f59e0b"],
104	];
105	
106	/** FNV-1a. Small, dependency-free, and stable across processes and deploys. */
107	function hash(input: string): number {
108	  let h = 0x811c9dc5;
109	  for (let i = 0; i < input.length; i++) {
110	    h ^= input.charCodeAt(i);
111	    h = Math.imul(h, 0x01000193) >>> 0;
112	  }
113	  return h >>> 0;
114	}
