116	export function coverFor(
117	  slug: string,
118	  brand: { primary: string; secondary: string } | null,
119	): WebsiteCover {
120	  if (brand) return { from: brand.primary, to: brand.secondary, source: "brand" };
121	  const [from, to] = COVER_PALETTES[hash(slug) % COVER_PALETTES.length];
122	  return { from, to, source: "slug" };
123	}
