125	/** One or two letters from the site's own name. Same rule as Avatar. */
126	export function monogramFor(name: string): string {
127	  const parts = name.trim().split(/[\s._-]+/).filter(Boolean);
128	  if (parts.length === 0) return "?";
129	  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
130	  return (parts[0][0] + parts[1][0]).toUpperCase();
