211	// ── Search params ──────────────────────────────────────────────────────────
212	
213	export type ViewMode = "grid" | "list";
214	export type SortKey = "updated" | "created" | "name";
215	
216	/**
217	 * The filters that can actually match something.
218	 *
219	 * "Archived" is absent and stays absent: there is no soft-delete column on
220	 * Project, and app/api/projects/[id]/route.ts states outright that delete is
221	 * irreversible with no archive. A filter that can never return a row is worse
222	 * than no filter, because it teaches the customer that their sites vanished.
223	 *
224	 * "Building" IS offered, but only under the staleness rule in BUILD_STALE_MS —
225	 * without it, one crashed SSE connection leaves a site filed under "Building"
226	 * permanently.
227	 */
228	export type StatusFilter = "all" | "published" | "draft" | "building";
229	
230	const VIEWS: Record<ViewMode, true> = { grid: true, list: true };
231	const SORTS: Record<SortKey, true> = { updated: true, created: true, name: true };
232	const STATUSES: Record<StatusFilter, true> = {
233	  all: true,
234	  published: true,
235	  draft: true,
236	  building: true,
237	};
238	
239	export type WebsiteParams = { view: ViewMode; sort: SortKey; status: StatusFilter; q: string };
240	
241	/** First value of a possibly-repeated query parameter, or null. */
242	function first(raw: string | string[] | undefined): string | null {
243	  if (typeof raw === "string") return raw;
244	  if (Array.isArray(raw) && typeof raw[0] === "string") return raw[0];
245	  return null;
246	}
247	
248	/**
249	 * `hasOwnProperty.call`, never `in`. `in` walks the prototype chain, so
250	 * `?view=constructor` or `?sort=toString` would pass a membership test against
251	 * an object literal and then index it to a function.
252	 */
253	function pick<T extends string>(table: Record<string, true>, raw: string | string[] | undefined, fallback: T): T {
254	  const value = first(raw);
255	  if (value === null) return fallback;
256	  return Object.prototype.hasOwnProperty.call(table, value) ? (value as T) : fallback;
257	}
258	
259	const QUERY_MAX = 80;
260	
261	export function readWebsiteParams(
262	  searchParams: Record<string, string | string[] | undefined>,
263	): WebsiteParams {
264	  const read = (key: string): string | string[] | undefined =>
265	    Object.prototype.hasOwnProperty.call(searchParams, key) ? searchParams[key] : undefined;
266	
267	  return {
268	    view: pick<ViewMode>(VIEWS, read("view"), "grid"),
269	    sort: pick<SortKey>(SORTS, read("sort"), "updated"),
270	    status: pick<StatusFilter>(STATUSES, read("status"), "all"),
271	    q: (first(read("q")) ?? "").slice(0, QUERY_MAX),
272	  };
273	}
