5	import { ToastProvider } from "@/components/ui/Toast";
6	import { MobileNav } from "./MobileNav";
7	import { Sidebar } from "./Sidebar";
8	
9	/* Collapse is persisted in a COOKIE, and its initial value is read on the
10	   server in app/(portal)/layout.tsx. localStorage is only readable after
11	   hydration, which would render a collapsed sidebar at full width and snap it
12	   narrow on every page load — the one animation nobody asked for. */
13	const COOKIE = "kodely-sidebar";
14	const YEAR = 60 * 60 * 24 * 365;
15	
16	/* The frame every portal page renders inside. Pages supply content only — no
17	   page owns its own navigation, header chrome or toast host, which is what
18	   let the old portal drift into several unrelated header treatments.
19	
20	   Collapse state lives HERE rather than inside Sidebar, because the main
21	   column's left offset has to move with the rail. When it lived in the
22	   sidebar the rail animated and the content stayed put, leaving a widening
23	   gap for the duration of the transition. */
24	export function AppShell({
25	  children,
26	  initialCollapsed,
27	  user,
28	  balance,
29	  avgBuildCredits,
30	  canTopUp,
31	}: {
32	  children: ReactNode;
33	  initialCollapsed: boolean;
34	  user: { email: string; name: string | null };
35	  balance: number;
36	  /** Their measured average build cost, used to phrase the balance as builds. */
37	  avgBuildCredits: number;
38	  /** billingEnabled(). False hides the top-up affordance rather than offering
39	      a button whose checkout call would come back 503. */
40	  canTopUp: boolean;
41	}) {
42	  const [collapsed, setCollapsed] = useState(initialCollapsed);
43	
44	  const toggle = () => {
45	    const next = !collapsed;
46	    setCollapsed(next);
47	    document.cookie = `${COOKIE}=${next ? "1" : "0"};path=/;max-age=${YEAR};samesite=lax`;
48	  };
49	
50	  return (
51	    <ToastProvider>
52	      <div className="k-shell min-h-dvh bg-canvas" data-collapsed={collapsed}>
53	        <Sidebar
54	          collapsed={collapsed}
55	          onToggle={toggle}
56	          user={user}
57	          balance={balance}
58	          avgBuildCredits={avgBuildCredits}
59	          canTopUp={canTopUp}
60	        />
61	        <MobileNav
62	          user={user}
63	          balance={balance}
64	          avgBuildCredits={avgBuildCredits}
65	          canTopUp={canTopUp}
66	        />
67	        {/* Both the rail's width and this offset read --shell-sidebar, so they
68	            animate off one value and cannot tear mid-transition. */}
69	        <div className="transition-[padding] duration-[var(--t-2)] ease-[var(--ease)] lg:pl-[var(--shell-sidebar)]">
70	          {/* pb-24 on small screens keeps the last row clear of the fixed
71	              bottom bar; without it the final card is permanently half-hidden
72	              and reads as a rendering bug. */}
73	          <main className="mx-auto w-full max-w-[1400px] px-4 pt-6 pb-24 sm:px-6 lg:px-8 lg:pt-8 lg:pb-14">
74	            {children}
75	          </main>
76	        </div>
77	      </div>
78	    </ToastProvider>
79	  );
80	}
