13	
14	/* The signed-in product shell: /dashboard/*, /settings, /support.
15	   Deliberately NOT wrapping /templates, /wizard, /pricing or /blog — those are
16	   public marketing pages with their own nav, and a signed-out visitor must
17	   still be able to read them. The portal has its own in-shell copies of the
18	   template gallery and the prompt entry for signed-in customers.
19	
20	   The builder (/projects/[id]) is also outside this group on purpose: it is
21	   full-bleed chat + preview and a 248px rail would take a fifth of the
22	   customer's site preview to show navigation they are not using while
23	   building. It carries its own back-to-dashboard affordance instead.
24	
25	   AUTH: this redirect is the primary gate, but every page below ALSO resolves
26	   the user itself. A layout does not re-render on every navigation within its
27	   own segment, and route handlers never sit under it at all — the same reason
28	   app/admin/layout.tsx says so in its own comment. */
29	export default async function PortalLayout({ children }: { children: ReactNode }) {
30	  const user = await getCurrentUser();
31	  if (!user) redirect("/login");
32	
33	  // Three cheap reads, all needed by the rail's credits card, which is on
34	  // every screen. averageBuildCredits() falls back to a global constant for
35	  // someone with no history, which is fine here — the card only uses it to
36	  // phrase the balance as "about N builds", never to claim it is *your*
37	  // average. Pages that make that stronger claim gate it on a build count.
38	  const [balance, avgBuildCredits, jar] = await Promise.all([
39	    getBalance(user.id),
40	    averageBuildCredits(user.id),
41	    cookies(),
42	  ]);
43	
44	  return (
45	    <AppShell
46	      initialCollapsed={jar.get("kodely-sidebar")?.value === "1"}
47	      user={{ email: user.email, name: user.name }}
48	      balance={balance}
49	      avgBuildCredits={avgBuildCredits}
50	      canTopUp={billingEnabled()}
51	    >
52	      {children}
53	    </AppShell>
54	  );
55	}
